test("a task that starts waiting for a usage limit sends one notification with its fixed text; resuming, waiting again or stopping does not send it a second time", async (t) => {
  const home = tempDir("botbench-push-limit-");
  t.after(() => fs.rmSync(home, { recursive: true, force: true }));
  const db = openStore(home);
  t.after(() => db.close());
  // A real HTTP endpoint in the place of the push service, and the real store that records what was sent.
  const endpoint = await startPushEndpoint();
  t.after(() => endpoint.close());
  const push = createPush({ db, home, allowHttpEndpoints: true });
  const phone = newDevice();
  push.subscribe(phone.subscription(endpoint.url("phone")));
  const titles = (): string[] => endpoint.received.map((r) => (JSON.parse(decrypt(r.body, phone.privateKey, phone.auth).toString()) as { title: string }).title);

  push.taskChanged({ id: 4, status: "waiting_for_limit" });
  await push.idle();
  assert.deepEqual(titles(), ["A task is waiting for a usage limit"]);
  assert.deepEqual(JSON.parse(decrypt(endpoint.received[0]!.body, phone.privateKey, phone.auth).toString()), usageLimitMessage({ id: 4 }));
  assert.deepEqual(usageLimitMessage({ id: 4 }), { title: "A task is waiting for a usage limit", path: "/#/tasks/4" });
  // Resumed, then waiting again, then stopped: the wait's notification is not sent again; the stop sends its own.
  for (const status of ["building", "waiting_for_limit", "building", "interrupted"]) push.taskChanged({ id: 4, status });
  await push.idle();
  assert.deepEqual(titles(), ["A task is waiting for a usage limit", "A task stopped"]);
  // Another Botbench over the same store, as after a restart, sends it no second time either.
  createPush({ db, home, allowHttpEndpoints: true }).taskChanged({ id: 4, status: "waiting_for_limit" });
  await push.idle();
  assert.equal(titles().filter((title) => title === "A task is waiting for a usage limit").length, 1);
});
